from collections.abc import Mapping
from copy import deepcopy
from itertools import islice


class DeviceCatalog:
    def __init__(self, records):
        self._records = {}
        self._replace(records)

    @staticmethod
    def _tag(tag):
        if not isinstance(tag, str):
            raise TypeError("tag must be a string")
        if not tag:
            raise ValueError("tag cannot be empty")
        return tag

    def _replace(self, records):
        if isinstance(records, (str, bytes)):
            raise TypeError("records must be an iterable of mappings")
        new_records = {}
        for record in records:
            if not isinstance(record, Mapping):
                raise TypeError("each record must be a mapping")
            if "tag" not in record:
                raise ValueError("record is missing tag")
            tag = self._tag(record["tag"])
            if tag in new_records:
                raise ValueError("duplicate tag")
            new_records[tag] = deepcopy(dict(record))
        self._records = new_records

    def locate(self, tag):
        tag = self._tag(tag)
        if tag not in self._records:
            raise ValueError("device not found")
        return deepcopy(self._records[tag])

    def await_tag(self, tag, snapshots, max_checks):
        tag = self._tag(tag)
        if isinstance(max_checks, bool) or not isinstance(max_checks, int):
            raise TypeError("max_checks must be an integer")
        if max_checks < 0:
            raise ValueError("max_checks cannot be negative")
        if tag in self._records:
            return deepcopy(self._records[tag])
        for snapshot in islice(snapshots, max_checks + 1):
            self._replace(snapshot)
            if tag in self._records:
                return deepcopy(self._records[tag])
        raise TimeoutError("device did not appear")

